window.kbPageData["views/entry/k-43fbc0d9fd6aabe3"] = {"key":"entry/k-43fbc0d9fd6aabe3","state":{"route":"entry/k-43fbc0d9fd6aabe3"},"node":{"id":"k-43fbc0d9fd6aabe3","mode":"k","title":"国内生产总值（GDP）","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2025 地市级 行测#28","国考 2025 行政执法 行测#28"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":1,"reviewSet":"多题条目","independentCount":1,"reviewDoubt":"未检索到针对国考 2025 地市级 行测 · 第 28 题的官方原题说明。B项中的“产值”是否特指增加值，或命题是否预设了足以判断增加值增长的条件，仍待核实。","tags":{"专题":["finance"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济","统计"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"directorySummary":"国内生产总值是一个国家或地区所有常住单位在一定时期内生产活动的最终成果。按生产法核算，等于各行业增加值之和。","review":{"title":"国内生产总值（GDP）","type":"概念与词义","definition":"国内生产总值是一个国家或地区所有常住单位在一定时期内生产活动的最终成果。按生产法核算，等于各行业增加值之和。","explanation":"符合常住单位条件的在华外资企业在境内生产形成的增加值计入中国GDP。增加值等于总产出减去中间投入，企业对GDP增长的贡献取决于同一核算口径下增加值的变动。","basis":"据关联原题及所列出处编释。","references":[{"source":"gdp","location":"定义和三种核算方法"},{"source":"web-2caa41b85888f544","location":"二、国内生产总值的三种核算方法（一）生产法","quote":"增加值＝总产出－中间投入"}],"examFocus":{"国考 2025 地市级 行测#28":"辨清GDP核算中生产地、企业所有权和产出指标各自的作用。"}},"aspects":[{"title":"在华外资企业的增加值归属","uses":[{"unit":"Q1","role":"直接考查","use":"本题，所给答案均为B。两卷解析以在华外资企业的生产成果纳入中国GDP说明核算归属。B项只给出企业产值持续增长，缺少判断其增加值是否增长的条件。","evidence":"外资企业CEO：我公司的产值持续增长，为中国GDP提升做出了贡献","qids":["国考 2025 地市级 行测#28","国考 2025 行政执法 行测#28"]}]}],"sources":[{"id":"0daa793a65a0589f","label":"国内生产总值（GDP）","topic":"经济指标与宏观调控","category":"非时政","text":"1.国内生产总值（GDP）\n国内（地区）生产总值是一个国家或地区的所有常住单位在一定时期内生产活动的全部\n最终产品的价值总和，是反映经济总体状况最重要的指标。\n——国家统计局","source":{"doc":"6cbfb01fe723bba64b75","first":3,"last":3,"page":3,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2025 地市级 行测#28":{"paper":"国考 2025 地市级 行测","n":28,"mod":"常识判断","src":["31f401e91aef8d11365d.pdf",4],"asrc":["8cece062c7c079b53130.pdf",10],"card":"c2dad9db7b25a88211acb607","links":[{"id":"k-43fbc0d9fd6aabe3","role":"直接考查","why":"GDP按常住单位的生产活动统计，在中国生产的外资企业对中国GDP有贡献。"}]},"国考 2025 行政执法 行测#28":{"paper":"国考 2025 行政执法 行测","n":28,"mod":"常识判断","src":["d8efe4e19862104d89c8.pdf",4],"asrc":["e2c4b1970d2b49eac0fd.pdf",10],"card":"eb6c988a8b5a2cd3328363e2","links":[{"id":"k-43fbc0d9fd6aabe3","role":"直接考查","why":"GDP核算以一定时期内常住单位的最终生产成果为口径，外资企业在中国境内生产的增加值计入中国GDP。"}]}},"terms":{},"references":{"gdp":{"name":"什么是国内生产总值（GDP） - 国家统计局","url":"https://www.stats.gov.cn/zs/tjws/tjzb/202301/t20230101_1903699.html"},"web-2caa41b85888f544":{"name":"国家统计局《什么是国内生产总值（GDP）》","url":"https://www.stats.gov.cn/zs/tjws/tjzb/202301/t20230101_1903699.html"}},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-43fbc0d9fd6aabe3":[["国考 2025 地市级 行测#28","国考 2025 行政执法 行测#28"]]}};
